import { Component } from '@angular/core';
import { count, doubled, items, increment, decrement, addItem } from './state/app.state';

@Component({
  selector: 'app-root',
  template: `<div>
    <h2>State Management with Signals</h2>
    <p>Count: {{ count() }}</p>
    <p>Doubled: {{ doubled() }}</p>
    <button (click)="increment()">+</button>
    <button (click)="decrement()">-</button>
    <input #newItem placeholder="Item baru">
    <button (click)="addItem(newItem.value); newItem.value=''">Tambah</button>
    <ul>
      <li *ngFor="let item of items()">{{ item }}</li>
    </ul>
  </div>`,
})
export class AppComponent {
  count = count;
  doubled = doubled;
  items = items;

  increment = increment;
  decrement = decrement;
  addItem = addItem;
}
